{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C20", "C74", "C78", "C80", "C81"],
  "contradictory_card_ids": ["C61", "C67"],
  "prediction_basis_card_ids": ["C20", "C74", "C78", "C80", "C81"],
  "claims": [
    {
      "claim": "C20 is the most direct threshold-relevant F measurement: compound 4p, a pyrazolopyrimidine acrylamide analog in the query's structural series, had an absolute oral Fpod of 10% in cynomolgus monkeys at 1 mg/kg, below the 20% threshold.",
      "card_ids": ["C20"]
    },
    {
      "claim": "L6 hepatic-clearance records for close BTK-inhibitor analogs show substantial hepatic metabolism: zanubrutinib HLM CYP3A intrinsic clearance 120 µL/(min·mg) and CYP-mediated hepatic metabolism as the major elimination route, plus acalabrutinib HLM intrinsic clearance 289.5 µL/(min·mg); this supports significant presystemic hepatic extraction.",
      "card_ids": ["C74", "C78", "C80", "C81"]
    },
    {
      "claim": "C61 and C67 show a close scaffold analog (compound 1k) has high Caco-2 permeability (Papp A→B 11.81 ×10^-6 cm/s) and no efflux (ER 1.03), indicating absorption is not the limiting step; this is consistent with first-pass hepatic metabolism rather than poor absorption as the cause of low F.",
      "card_ids": ["C61", "C67"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C74", "C78", "C80", "C81"]
    }
  ],
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the query itself; C20 is a monkey Fpod for an analog and its structure is not shown on the card.",
    "L6 records are human/rat liver microsome intrinsic-clearance values for close analogs, not query-specific F measurements; in vitro-in vivo scaling and species differences limit quantitative transfer.",
    "No experimental solubility or metabolic-stability data for the query; high logD/logP is only a proxy for a solubility liability.",
    "No IV comparator for the query or close analogs in the L3/L4 exposure records, so absolute F cannot be calculated from those data."
  ],
  "decision_summary": "The most direct threshold-relevant evidence remains C20 (monkey absolute Fpod 10% for a pyrazolopyrimidine acrylamide analog, below 20%). L6 adds mechanistic support: close BTK-inhibitor analogs (zanubrutinib, acalabrutinib) show high HLM intrinsic clearance and CYP-mediated hepatic metabolism, consistent with substantial first-pass loss. High permeability and absent efflux in a close scaffold analog (C61/C67) indicate absorption is not the limiting step. Prediction remains low, with moderate confidence, strengthened by the L6 clearance evidence."
}

